import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv, vec2, vec3, color, mix, smoothstep, texture, sin, positionLocal,
  normalLocal, normalize, float, clamp
} from 'three/tsl';
import { gsap } from 'gsap';

// COMPOSITION: a graded 3-stop gradient backdrop (7x6 @ z=-3) frames a machined
//   pedestal (cylinder, chamfered ink rim) sitting at y~-0.6; a brushed-titanium
//   torus knot floats centered at [0,0.4,0] as the sole hero, with headline +
//   caption plates stacked below on the 0.25-unit rhythm and a signal-red accent
//   tick on the pedestal face for the one permitted accent read.
// LIGHT RIG (rig-top-museum): spot key #fff6ea @[0,4,0.2] -> [0,0.2,0] (angle .4,
//   penumbra .5), directional fill #dcd8d0 @[-2,1.6,2.4] -> [0,0.4,0], point rim
//   #ffffff @[1.4,1,-2.2], plus a 0.12 ambient floor and a soft hemisphere fill
//   standing in for the neutral studio PMREM IBL that reveals anisotropy streaks.
// MATERIAL STRATEGY: knot = MeshPhysicalNodeMaterial with a roughnessMap texture
//   node (brushed-metal.map.png) re-centered at 0.9 and multiplied by base 0.55,
//   procedural scratch-noise normal perturbation (strength .15) + 2% roughness
//   jitter, anisotropy 0.9 rotated 90deg to the tube; pedestal = surface PBR with
//   an ink-colored chamfer torus catching the key light; contact shadow = radial
//   falloff plane; accent = emissive signal-red bar.
// MOTION: weighted-settle scale-in (1.04->1.0, power4.out, 0.9s) on load, plus the
//   orbit cinematic primitive driving the knot's slow y-rotation (0.1 rad/s).
// FOCAL ELEMENT: the brushed-titanium torus knot is the single brightest, most
//   detailed object in frame; everything else (pedestal, text, accent) is graded
//   below it in value and saturation.

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'pedestal-material-study';

  const disposables = { geometries: [], materials: [], textures: [] };
  const primitiveHandles = [];
  const tweens = [];

  const colors = (config.intent?.visualSpec?.colors) ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.7, hex: '#101017' }, { at: 1, hex: '#16161d' }]
  };

  // ---- BACKDROP: 7x6 plane @ z=-3, vertical 3-stop gradient ----------------
  {
    const geo = new THREE.PlaneGeometry(7, 6, 1, 1);
    const mat = new MeshBasicNodeMaterial({ side: THREE.DoubleSide });
    const t = uv().y;
    const stops = colors.gradientStops ?? [
      { at: 0, hex: colors.background }, { at: 0.7, hex: '#101017' }, { at: 1, hex: colors.ink }
    ];
    const c0 = color(stops[0].hex);
    const c1 = color(stops[1].hex);
    const c2 = color(stops[2].hex);
    const stage1 = mix(c0, c1, smoothstep(float(stops[0].at), float(stops[1].at), t));
    const gradient = mix(stage1, c2, smoothstep(float(stops[1].at), float(stops[2].at), t));
    mat.colorNode = gradient;
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0, 0, -3);
    group.add(mesh);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
  }

  // ---- PEDESTAL: cylinder r1.1 h0.5, top face at y=-0.35 -------------------
  const pedestalGroup = new THREE.Group();
  pedestalGroup.position.set(0, -0.6, 0);
  {
    const geo = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 48);
    const mat = new MeshPhysicalNodeMaterial({
      color: new THREE.Color(colors.surface),
      roughness: 0.7,
      metalness: 0.35,
      clearcoat: 0.08
    });
    const mesh = new THREE.Mesh(geo, mat);
    pedestalGroup.add(mesh);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);

    // chamfered top edge (ink-colored ring catching key light)
    const chamferGeo = new THREE.TorusGeometry(1.075, 0.03, 8, 64);
    const chamferMat = new MeshPhysicalNodeMaterial({
      color: new THREE.Color(colors.ink),
      roughness: 0.4,
      metalness: 0.45,
      clearcoat: 0.2,
      clearcoatRoughness: 0.3
    });
    const chamfer = new THREE.Mesh(chamferGeo, chamferMat);
    chamfer.rotation.x = Math.PI / 2;
    chamfer.position.set(0, 0.25, 0);
    pedestalGroup.add(chamfer);
    disposables.geometries.push(chamferGeo);
    disposables.materials.push(chamferMat);

    // accent tick — single signal-red read
    const accentGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.14, 8);
    const accentMat = new MeshPhysicalNodeMaterial({
      color: new THREE.Color(colors.accent),
      emissive: new THREE.Color(colors.accent),
      emissiveIntensity: 1.4,
      roughness: 0.4,
      metalness: 0.1
    });
    const accent = new THREE.Mesh(accentGeo, accentMat);
    accent.position.set(0, -0.18, 1.08);
    pedestalGroup.add(accent);
    disposables.geometries.push(accentGeo);
    disposables.materials.push(accentMat);
  }
  group.add(pedestalGroup);

  // ---- CONTACT SHADOW: radial falloff plane @ y=-0.36, r1.5 ---------------
  {
    const geo = new THREE.CircleGeometry(1.5, 64);
    const mat = new MeshBasicNodeMaterial({
      color: new THREE.Color(0x000000),
      transparent: true,
      side: THREE.DoubleSide,
      depthWrite: false
    });
    const dist = uv().sub(vec2(0.5, 0.5)).length().mul(2.0);
    const fadeStart = float(1.1 / 1.5);
    const opacity = float(0.6).mul(float(1.0).sub(smoothstep(fadeStart, float(1.0), dist)));
    mat.opacityNode = opacity;
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(0, -0.36, 0);
    group.add(mesh);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
  }

  // ---- TORUS KNOT: hero material study -------------------------------------
  const knotGroup = new THREE.Group();
  knotGroup.position.set(0, 0.4, 0);
  const knotGeo = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.paper),
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35
  });
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2; // 90deg to tube direction

  const roughTex = new THREE.Texture();
  const roughTexNode = texture(roughTex);
  const mapCentered = roughTexNode.r.mul(0.2).add(0.9);
  const roughnessBase = mapCentered.mul(0.55);
  const jitter = sin(positionLocal.x.mul(300.0).add(positionLocal.y.mul(450.0))).mul(0.02);
  knotMat.roughnessNode = clamp(roughnessBase.add(jitter), float(0.05), float(0.95));

  const scratch = vec3(
    sin(positionLocal.x.mul(80.0)).mul(0.15),
    sin(positionLocal.y.mul(95.0).add(1.3)).mul(0.15),
    float(0.0)
  );
  knotMat.normalNode = normalize(normalLocal.add(scratch));

  const knotMesh = new THREE.Mesh(knotGeo, knotMat);
  knotGroup.add(knotMesh);
  group.add(knotGroup);
  disposables.geometries.push(knotGeo);
  disposables.materials.push(knotMat);

  let loadedRoughTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    roughTexNode.value = tex;
    loadedRoughTex = tex;
  }).catch(() => {});

  // ---- LIGHT RIG (rig-top-museum) ------------------------------------------
  const lightGroup = new THREE.Group();
  const ambient = new THREE.AmbientLight(0xffffff, 0.12);
  lightGroup.add(ambient);

  const key = new THREE.SpotLight(0xfff6ea, 75, 0, 0.4, 0.5, 2);
  key.position.set(0, 4, 0.2);
  const keyTarget = new THREE.Object3D();
  keyTarget.position.set(0, 0.2, 0);
  lightGroup.add(keyTarget);
  key.target = keyTarget;
  lightGroup.add(key);

  const fill = new THREE.DirectionalLight(0xdcd8d0, 0.4);
  fill.position.set(-2, 1.6, 2.4);
  const fillTarget = new THREE.Object3D();
  fillTarget.position.set(0, 0.4, 0);
  lightGroup.add(fillTarget);
  fill.target = fillTarget;
  lightGroup.add(fill);

  const rim = new THREE.PointLight(0xffffff, 7, 8, 2);
  rim.position.set(1.4, 1, -2.2);
  lightGroup.add(rim);

  const studioFill = new THREE.HemisphereLight(0xe8ecf2, 0x0b0b10, 0.7);
  lightGroup.add(studioFill);

  group.add(lightGroup);

  // ---- TEXT: headline + caption on 0.25-unit rhythm ------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Material study 03', role: 'headline' },
    { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', role: 'caption' }
  ];

  const textNodes = [];
  for (const item of items) {
    if (item.role === 'headline') {
      const headline = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: colors.paper,
        align: 'center'
      });
      headline.position.set(0, -1.2, 0);
      group.add(headline);
      textNodes.push(headline);
    } else if (item.role === 'caption') {
      const caption = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: colors.paper,
        align: 'center',
        letterSpacingPx: 0.08
      });
      caption.position.set(0, -1.6, 0);
      group.add(caption);
      textNodes.push(caption);
    }
  }

  // ---- CINEMATIC PRIMITIVES -------------------------------------------------
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const target = prim.name === 'orbit' ? knotGroup : group;
      const handle = fn(target, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- ENTRANCE MOTION: weighted-settle -------------------------------------
  group.scale.setScalar(1.04);
  const settleTween = gsap.to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  });
  tweens.push(settleTween);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    for (const tw of tweens) tw.kill();
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') handle.cleanup();
      if (handle && handle.timeline && typeof handle.timeline.kill === 'function') handle.timeline.kill();
    }
    for (const geo of disposables.geometries) geo.dispose?.();
    for (const mat of disposables.materials) mat.dispose?.();
    for (const tex of disposables.textures) tex.dispose?.();
    if (loadedRoughTex) loadedRoughTex.dispose?.();
    for (const t of textNodes) {
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    }
  };

  return group;
}

