  {"id":"text.caption.1","where":"createNode/text-loop","how":"ctx.fontAtlas.createText caption at y=-1.6"},
  {"id":"color.background","where":"createNode/backdrop-block","how":"gradientStops[0] hex used as c0 in gradient mix"},
  {"id":"color.surface","where":"createNode/pedestal-block","how":"pedestal cylinder MeshPhysicalNodeMaterial color"},
  {"id":"color.ink","where":"createNode/pedestal-block-chamfer","how":"chamfer torus ring material color"},
  {"id":"color.paper","where":"createNode/knot-material + text-loop","how":"knot base color and text fontAtlas color"},
  {"id":"color.accent","where":"createNode/pedestal-block-accent","how":"emissive accent cylinder tick color"},
  {"id":"color.gradient","where":"createNode/backdrop-block","how":"3-stop smoothstep mix over uv().y"},
